		return CkPem_PublicKeyAt($this->_cPtr,$index,$pubKey);
	}

	/**
	 * Removes  the Nth certificate from the PEM.  The first certificate is at index 0.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPemRef.html#RemoveCert
	 * @param int $index
	 * @return bool
	 */
	function RemoveCert($index) {
		return CkPem_RemoveCert($this->_cPtr,$index);
	}

	/**
	 * Removes  the Nth private key from the PEM.  The first private key is at index 0.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPemRef.html#RemovePrivateKey
	 * @param int $index
	 * @return bool
	 */
	function RemovePrivateKey($index) {
		return CkPem_RemovePrivateKey($this->_cPtr,$index);
	}

	/**
	 * Applications should instead call ToJksObj. Converts the PEM to JKS and returns the Java KeyStore object.   If the ARG1 is non-empty, the 1st object (private key or certificate) will use the alias, and all others (if any) will receive auto-generated aliases. The JKS returned will be encrypted using the provided ARG2.   If the PEM contains only certificates (no private keys), then the ARG2 is unused.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPemRef.html#ToJks
	 * @param ?string $alias
	 * @param ?string $password
	 * @return ?CkJavaKeyStore
	 * @deprecated
	 */
	function ToJks($alias,$password) {
		return chilkat::_obj(CkPem_ToJks($this->_cPtr,$alias,$password),'CkJavaKeyStore');
	}

	/**
	 * This function converts this PEM to a Java KeyStore (JKS) object and stores it in ARG3. If ARG1 is provided, it will be used as the alias for the first object in the PEM (either a private key or certificate), while subsequent objects will receive autogenerated aliases. The resulting JKS will be encrypted with ARG2, unless the PEM contains only certificates, in which case ARG2 is not used.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPemRef.html#ToJksObj
	 * @param ?string $alias
	 * @param ?string $password
	 * @param CkJavaKeyStore $jksObj
	 * @return bool
	 */
	function ToJksObj($alias,$password,$jksObj) {
		return CkPem_ToJksObj($this->_cPtr,$alias,$password,$jksObj);
	}

	/**
	 * Write the PFX to a PEM formatted string.  The resultant PEM will contain the private key, as well as the certs in the chain of authentication (or whatever certs are available in the PFX).  For example:
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPemRef.html#ToPem
	 * @return ?string
	 */
	function toPem() {
		return CkPem_toPem($this->_cPtr);
	}

	/**
	 * Write the PFX to a PEM formatted string.  If ARG1 is _TRUE_, then extended properties (Bag Attributes and Key Attributes) are output.  If ARG2 is _TRUE_, then no private keys are output. If ARG3 is _TRUE_, then no certificates are output.  If ARG4 is _TRUE_, then  no CA certs or intermediate CA certs are output.  If ARG5 is not empty, it indicates the encryption algorithm to be used for encrypting the private keys (otherwise the private keys are output unencrypted).  The possible choices for the ARG5 are des3, aes128, aes192, and aes256.  (All encryption algorithm choices use CBC mode.) If the private keys are to be encrypted, then ARG6 is the password to be used. Otherwise, ARG6 may be left empty.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPemRef.html#ToPemEx
	 * @param bool $extendedAttrs
	 * @param bool $noKeys
	 * @param bool $noCerts
	 * @param bool $noCaCerts
	 * @param ?string $encryptAlg
	 * @param ?string $password
	 * @return ?string
	 */
	function toPemEx($extendedAttrs,$noKeys,$noCerts,$noCaCerts,$encryptAlg,$password) {
		return CkPem_toPemEx($this->_cPtr,$extendedAttrs,$noKeys,$noCerts,$noCaCerts,$encryptAlg,$password);
	}

	/**
	 * Applications should instead call ToPfxObj. Converts this PEM object, which must contain at least one private key, to PKCS12 and returns the PFX object. Typically, a PKCS12 file includes one private key, its associated certificate, and the certificate chain.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPemRef.html#ToPfx
	 * @return ?CkPfx
	 * @deprecated
	 */
	function ToPfx() {
		return chilkat::_obj(CkPem_ToPfx($this->_cPtr),'CkPfx');
	}

	/**
	 * Converts this PEM object, which must contain at least one private key, to PKCS12 and returns the PFX in ARG1. Typically, a PKCS12 file includes one private key, its associated certificate, and the certificate chain.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPemRef.html#ToPfxObj
	 * @param CkPfx $pfxObj
	 * @return bool
	 */
	function ToPfxObj($pfxObj) {
		return CkPem_ToPfxObj($this->_cPtr,$pfxObj);
	}
}
